[data-theme="brutalist"] .drag-hint { color: #000000; border: 1px dashed rgba(0,0,0,0.45); background: rgba(255,255,255,0.85); text-transform: uppercase; letter-spacing: 0.1em; font-family: "JetBrains Mono", monospace; }

