[data-theme="swiss"] .kv .n { color: #d92b2b; font-weight: 700; }
[data-theme="swiss"] .picked-flag { background: #d92b2b; color: #ffffff; border-radius: 0; text-transform: uppercase; letter-spacing: 0.1em; }
