[data-theme="synthwave"] body::before {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background: radial-gradient(120% 55% at 50% 110%, rgba(255,62,200,0.18), rgba(255,62,200,0.05) 45%, rgba(255,62,200,0) 72%), linear-gradient(to top, rgba(46,230,255,0.04), rgba(46,230,255,0) 28%);
}
[data-theme="synthwave"] h1, [data-theme="synthwave"] h2 {
  text-transform: uppercase; letter-spacing: 0.05em;
}
[data-theme="synthwave"] h1 em, [data-theme="synthwave"] h2 em {
  font-style: normal; color: #ff7adb;
  text-shadow: 0 0 10px rgba(255,62,200,0.85), 0 0 34px rgba(255,62,200,0.4);
}
[data-theme="synthwave"] .hero h1 em {
  background: linear-gradient(100deg, #ff3ec8 8%, #ff8a3d 48%, #2ee6ff 95%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent; color: transparent;
  text-shadow: none; filter: drop-shadow(0 0 16px rgba(255,62,200,0.45));
}
[data-theme="synthwave"] .btn, [data-theme="synthwave"] .cta-btn { border-radius: 999px; }
[data-theme="synthwave"] .cta-btn {
  background: linear-gradient(135deg, #ff3ec8, #d81fff);
  color: #fff5fc; border: 1px solid rgba(255,150,222,0.7);
  text-shadow: 0 0 8px rgba(255,255,255,0.45);
  box-shadow: 0 0 18px rgba(255,62,200,0.55), 0 0 52px rgba(255,62,200,0.22), inset 0 0 12px rgba(255,255,255,0.14);
  transition: box-shadow 0.25s ease;
}
[data-theme="synthwave"] .cta-btn:hover {
  box-shadow: 0 0 28px rgba(255,62,200,0.85), 0 0 80px rgba(255,62,200,0.35), inset 0 0 16px rgba(255,255,255,0.22);
}
[data-theme="synthwave"] .page-frame {
  border: 1px solid rgba(46,230,255,0.42);
  box-shadow: 0 0 22px rgba(46,230,255,0.16), inset 0 0 26px rgba(46,230,255,0.05);
}
[data-theme="synthwave"] .card {
  background: linear-gradient(165deg, rgba(40,9,76,0.55), rgba(14,0,29,0.75));
  transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
[data-theme="synthwave"] .card:hover {
  border-color: rgba(46,230,255,0.55);
  box-shadow: 0 0 20px rgba(46,230,255,0.18), inset 0 0 18px rgba(46,230,255,0.05);
}
[data-theme="synthwave"] .access-card {
  background: linear-gradient(180deg, rgba(42,10,80,0.82), rgba(18,0,36,0.92));
  border: 1px solid rgba(255,62,200,0.38);
  box-shadow: 0 0 34px rgba(255,62,200,0.14), inset 0 0 24px rgba(255,62,200,0.05);
}
[data-theme="synthwave"] .refs .ref { border-radius: 999px; border: 1px solid rgba(46,230,255,0.32); }
[data-theme="synthwave"] .refs .ref:hover {
  border-color: rgba(255,62,200,0.65); box-shadow: 0 0 14px rgba(255,62,200,0.3);
}
[data-theme="synthwave"] .tag {
  border-radius: 999px; border: 1px solid rgba(46,230,255,0.3);
  color: #6ee7ff; text-shadow: 0 0 6px rgba(46,230,255,0.45);
}
[data-theme="synthwave"] .picked-flag { color: #ff3ec8; text-shadow: 0 0 10px rgba(255,62,200,0.7); }
[data-theme="synthwave"] .kv .n { color: #2ee6ff; text-shadow: 0 0 8px rgba(46,230,255,0.5); }
[data-theme="synthwave"] .readout { border: 1px solid rgba(46,230,255,0.26); box-shadow: inset 0 0 14px rgba(46,230,255,0.05); }
[data-theme="synthwave"] .drag-hint { color: #b07ff5; text-shadow: 0 0 8px rgba(157,107,255,0.5); }
[data-theme="synthwave"] ::selection { background: rgba(255,62,200,0.45); color: #fff8fd; }

[data-theme="mission"] h1, [data-theme="mission"] h2, [data-theme="mission"] h3 { font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.06em; }
[data-theme="mission"] .hero h1 { text-shadow: 0 0 24px rgba(234,242,255,0.18); }
