[data-theme="mission"] .page-frame { border-color: rgba(255,176,0,0.18); }
[data-theme="mission"] .cta-btn { background: #ffb000; color: #080d18; border: 1px solid #ffb000; border-radius: 3px; font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600; }
[data-theme="mission"] .cta-btn:hover { background: #ffc94d; border-color: #ffc94d; box-shadow: 0 0 18px rgba(255,176,0,0.35); }
[data-theme="mission"] .btn { border-radius: 3px; font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.08em; }
[data-theme="mission"] .tag { font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.07em; color: #ffb000; border: 1px solid rgba(255,176,0,0.32); border-radius: 2px; background: rgba(255,176,0,0.06); }
