[data-theme="mission"] .refs .ref:hover { border-color: rgba(255,176,0,0.6); color: #ffb000; }
[data-theme="mission"] .picked-flag { color: #3adb76; font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.08em; text-shadow: 0 0 10px rgba(58,219,118,0.45); }
[data-theme="mission"] .tp-toggle, [data-theme="mission"] .tp-panel { border: 1px solid rgba(255,176,0,0.3); border-radius: 2px; background: rgba(8,13,24,0.82); font-family: "IBM Plex Mono", monospace; }
[data-theme="mission"] .drag-hint { font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.1em; color: #5a6c8c; }
