[data-theme="noir"] .page-frame { border: 1px solid rgba(201, 169, 106, 0.2); }
[data-theme="noir"] .readout, [data-theme="noir"] .titleblock, [data-theme="noir"] .drag-hint { font-family: "JetBrains Mono", ui-monospace, monospace; font-weight: 300; letter-spacing: 0.08em; color: #b3ab99; }
[data-theme="noir"] .kv .n { font-family: "JetBrains Mono", ui-monospace, monospace; color: #c9a96a; }
[data-theme="noir"] .refs .ref { background: transparent; border: 1px solid rgba(201, 169, 106, 0.16); border-radius: 0; font-family: "JetBrains Mono", ui-monospace, monospace; letter-spacing: 0.05em; transition: border-color 200ms ease, color 200ms ease; }
[data-theme="noir"] .refs .ref:hover { border-color: rgba(201, 169, 106, 0.6); color: #f5efe2; }
[data-theme="noir"] .picked-flag { color: #101010; background: #c9a96a; border-radius: 0; font-family: "JetBrains Mono", ui-monospace, monospace; letter-spacing: 0.14em; text-transform: uppercase; }
[data-theme="noir"] .tp-toggle, [data-theme="noir"] .tp-panel { background: rgba(12, 11, 9, 0.82); border: 1px solid rgba(201, 169, 106, 0.25); border-radius: 0; }
[data-theme="noir"] ::selection { background: #c9a96a; color: #101010; }

[data-theme="acid"] ::selection{background:#9dff00;color:#14171a}
[data-theme="acid"] body{background-image:radial-gradient(rgba(20,23,26,0.055) 1px,transparent 1px);background-size:22px 22px}
[data-theme="acid"] h1,[data-theme="acid"] h2,[data-theme="acid"] h3{font-weight:600;letter-spacing:-0.03em}
[data-theme="acid"] .hero h1{font-weight:600;letter-spacing:-0.045em;line-height:0.96}
[data-theme="acid"] .tag{background:#9dff00;color:#14171a;border:1.5px solid #14171a;border-radius:999px;padding:0.22em 0.85em;font-weight:600;letter-spacing:0.01em}
[data-theme="acid"] .card{background:#f5f7f2;border:2px solid #14171a;border-radius:18px;box-shadow:4px 4px 0 rgba(20,23,26,0.14);transition:transform .15s ease,box-shadow .15s ease}
[data-theme="acid"] .card:hover{transform:translate(-2px,-2px);box-shadow:6px 6px 0 #14171a}
[data-theme="acid"] .access-card{background:#f5f7f2;border:2px solid #14171a;border-radius:18px;box-shadow:6px 6px 0 #6a00ff}
[data-theme="acid"] .cta-btn{background:#6a00ff;color:#ffffff;border:2px solid #14171a;border-radius:999px;font-weight:600;box-shadow:3px 3px 0 #14171a;transition:transform .12s ease,box-shadow .12s ease}
[data-theme="acid"] .cta-btn:hover{transform:translate(-1px,-1px);box-shadow:4px 4px 0 #14171a;background:#5a00da}
[data-theme="acid"] .cta-btn:active{transform:translate(2px,2px);box-shadow:1px 1px 0 #14171a}
[data-theme="acid"] .btn{border:2px solid #14171a;border-radius:999px;font-weight:600;background:#f5f7f2;color:#14171a}
[data-theme="acid"] .btn:hover{background:#9dff00}
[data-theme="acid"] .picked-flag{transform:rotate(-3deg);background:#9dff00;color:#14171a;border:2px solid #14171a;border-radius:7px;box-shadow:2px 2px 0 #14171a;font-weight:700;letter-spacing:0.02em}
[data-theme="acid"] .refs .ref{border:1.5px solid #14171a;border-radius:999px;background:#f5f7f2;color:#14171a;transition:background .12s ease,transform .12s ease}
[data-theme="acid"] .refs .ref:hover{background:#9dff00;transform:translateY(-1px)}
[data-theme="acid"] .readout{border:1.5px solid rgba(20,23,26,0.65);border-radius:10px;background:rgba(233,235,231,0.78)}
[data-theme="acid"] .kv .n{color:#6a00ff;font-weight:700}
[data-theme="acid"] .titleblock{border:2px solid #14171a;border-radius:12px;background:rgba(245,247,242,0.85)}
[data-theme="acid"] .tp-toggle{border:2px solid #14171a;border-radius:999px;background:#f5f7f2;box-shadow:2px 2px 0 #14171a;font-weight:600}
[data-theme="acid"] .tp-panel{border:2px solid #14171a;border-radius:14px;background:rgba(245,247,242,0.94);box-shadow:5px 5px 0 rgba(20,23,26,0.16)}
[data-theme="acid"] .page-frame{border-color:rgba(20,23,26,0.8)}
[data-theme="acid"] .drag-hint{color:#43494f;border:1.5px dashed rgba(20,23,26,0.45);border-radius:999px;background:rgba(233,235,231,0.78)}
